sources.check-library.lua:
return rule('demo.lib.check', {'actor','skill'}, function(r, actor, skill)
  r.ownedSkill(actor, skill)
  local target = r.number(skill, 'value')
  local rolled = r.roll(100)
  return {target=target, rolled=rolled, passed=rolled<=target}
end, {public=false})

sources.damage-library.lua:
return rule('demo.lib.damage', {'actor','amount'}, function(r, actor, amount)
  local lost = math.max(0, amount-r.number(actor,'armor'))
  r.set(actor, 'hp', math.max(0,r.number(actor,'hp')-lost))
end, {public=false})

