sources.rules.lua:
return rule('demo.check', {'actor','skill'}, function(r, actor, skill)
  return r.check(actor, skill).passed
end)

sources.ruling.lua:
return flow('demo.ruling', {'actor','skill','amount'}, {
  step('check', function(r, actor, skill) return r.check(actor,skill).passed end,
       {yes='end', no='ruling'}),
  ask('ruling', {role='kp', seconds=60, yes='apply', no='end', timeout='end'}),
  step('apply', function(r, actor, skill, amount) r.damage(actor,amount) end)
})

sources.timed.lua:
return flow('demo.timed', {'actor','amount'}, {
  ask('choice', {role='initiator', seconds=30, yes='apply', no='end', timeout='end'}),
  step('apply', function(r, actor, amount) r.damage(actor,amount) end)
})

sources.transfer-library.lua:
return rule('demo.lib.transfer', {'item','bag','quantity'}, function(r, item, bag, quantity)
  local load = 0
  for _, entry in ipairs(r.items(bag)) do
    load = load + entry.numbers.quantity*entry.numbers.unitMass
  end
  local itemData = r.read(item)
  quantity = quantity or itemData.numbers.quantity
  assert(load + quantity*itemData.numbers.unitMass <= r.number(bag,'capacity'), 'capacity exceeded')
  return r.move(item, bag, quantity)
end, {public=false})

